for dom in d["domains"]:
    if dom["id"] == "threatlocker-assessment-prep":
        dom["scenarios"] = main_scenarios
        break

with open(P, "w") as f:
    json.dump(d, f, indent=2, ensure_ascii=True)
    f.write("\n")

